export function parseA1Range(text) {
  if (typeof text !== 'string') return null;
  const match = A1_RANGE.exec(text.trim());
  if (!match) return null;
  const c1 = columnIndex(match[1]);
  const r1 = Number.parseInt(match[2], 10) - 1;
  const c2 = match[3] === undefined ? c1 : columnIndex(match[3]);
  const r2 = match[4] === undefined ? r1 : Number.parseInt(match[4], 10) - 1;
  return {
    r1: Math.min(r1, r2),
    c1: Math.min(c1, c2),
    r2: Math.max(r1, r2),
    c2: Math.max(c1, c2),
  };
}
export function formatA1Range(rect) {
  const start = `${columnLabel(rect.c1)}${rect.r1 + 1}`;
  if (rect.r1 === rect.r2 && rect.c1 === rect.c2) return start;
  return `${start}:${columnLabel(rect.c2)}${rect.r2 + 1}`;
}

/**
 * A1-notation primitives shared by the backend structure endpoints and the
 * formula engine (sub-issue C, Issue #5 decision D-C1/D-C7).
 *
 * This module was migrated verbatim from `backend/src/ranges.js` (sub-issue B,
 * Issue #4 comment #35 D-B3) so that both consumers map coordinates through a
 * single implementation: `backend/src/ranges.js` re-exports the public names
 * and keeps its behaviour byte-for-byte.
 *
 * Two views of the same coordinate mapping:
 *
 * - **range view** (`shiftRangeOnInsert` / `shiftRangeOnDelete`) formats the
 *   result with {@link formatA1Range}, which strips `$` markers, collapses a
 *   1x1 rectangle to a single reference and uppercases the column letters. It
 *   is what B persists for validation rules, filters and pivot source ranges.
 * - **rect view** (`shiftRectOnInsert` / `shiftRectOnDelete`) returns the
 *   mapped rectangle without formatting, so the formula engine can re-emit a
 *   reference preserving the user's `$` markers, `:` separator and letter case
 *   (Issue #5 decision D-C4).
 *
 * Mapping rules (Issue #4 comment #35 D-B3):
 *
 * - Insert at the new block's first index `p`, `count` slots: `p <= r1` shifts
 *   the whole range; `r1 < p <= r2` expands the range by `count` (an insertion
 *   inside a region stays inside it); `p > r2` changes nothing.
 * - Delete at `d`: `d < r1` shifts the whole range; `r1 <= d <= r2` shrinks it
 *   by one with `r1` fixed (`r2 -= 1`); a range that collapses (`r1 > r2`,
 *   i.e. exactly the deleted single row/column) is reported as `null`.
 *
 * Parsing is deliberately lenient: any expression this module cannot parse is
 * returned unchanged (`changed: false`) so an unknown stored format is never
 * corrupted by a structure operation.
 */

/** @typedef {{ r1: number, c1: number, r2: number, c2: number }} Rect */
/** @typedef {'row' | 'column'} Axis */
